package git.shin.adfree.update

import org.junit.Assert.assertEquals
import org.junit.Test

class ReleaseNotesTest {
    private val body =
        """
        ## [1.27.0](https://example.test/compare/v1.26.0...v1.27.0) (2026-11-20)

        ### Features

        * **desktop:** an update screen with the release notes
        * the installer it picks

        ### Bug Fixes

        * **proxy:** a socket is a socket

        <!-- generated by semantic-release -->
        """.trimIndent()

    @Test
    fun theHeadingsKeepTheWordsAndLoseTheHashes() {
        assertEquals(
            listOf("1.27.0 (2026-11-20)", "Features", "Bug Fixes"),
            ReleaseNotes.lines(body).filter { it.kind == ReleaseNotes.Kind.HEADING }.map { it.text },
        )
    }

    @Test
    fun aBulletIsABulletWithoutItsMarker() {
        val bullets = ReleaseNotes.lines(body).filter { it.kind == ReleaseNotes.Kind.BULLET }.map { it.text }
        assertEquals(
            listOf(
                "desktop: an update screen with the release notes",
                "the installer it picks",
                "proxy: a socket is a socket",
            ),
            bullets,
        )
    }

    @Test
    fun theGeneratedCommentAndTheBlankLinesAreNotLines() {
        val all = ReleaseNotes.lines(body).map { it.text }
        assertEquals(false, all.any { "semantic-release" in it })
        assertEquals(false, all.any { it.isBlank() })
    }

    @Test
    fun aCodeSpanKeepsItsWordsAndLosesItsTicks() {
        assertEquals("run a now", ReleaseNotes.inline("run `a` now"))
        assertEquals("npm test", ReleaseNotes.inline("`npm test`"))
    }

    @Test
    fun aLinkKeepsItsLabelAndLosesItsAddress() {
        assertEquals(
            "1.27.0",
            ReleaseNotes.inline("[1.27.0](https://example.test/compare/v1.26.0...v1.27.0)"),
        )
    }

    @Test
    fun aRuleIsNotContent() {
        assertEquals(emptyList<ReleaseNotes.Line>(), ReleaseNotes.lines("---"))
    }
}
